class AuditStore:
    __slots__ = ("__events",)

    def __init__(self) -> None:
        self.__events: tuple[dict, ...] = ()

    def append(self, event: dict) -> None:
        self.__events = self.__events + (dict(event),)

    def events(self) -> list[dict]:
        return [dict(event) for event in self.__events]

    def __len__(self) -> int:
        return len(self.__events)


def migrate_event(row: dict) -> dict:
    timestamp = row["EVT_TS"]
    return {
        "evt_id": int(row["EVT_ID"]),
        "ts": (
            timestamp[0:4]
            + "-"
            + timestamp[4:6]
            + "-"
            + timestamp[6:8]
            + "T"
            + timestamp[8:10]
            + ":"
            + timestamp[10:12]
            + ":"
            + timestamp[12:14]
        ),
        "code": row["EVT_CD"],
        "user_id": row["USR_ID"],
        "entity": row["ENT_NAME"],
        "entity_id": row["ENT_ID"],
        "old_val": row["OLD_VAL"],
        "new_val": row["NEW_VAL"],
    }


def migrate(rows: list[dict], store: AuditStore | None = None) -> AuditStore:
    target = AuditStore() if store is None else store
    present = {event["evt_id"] for event in target.events()}

    for row in sorted(rows, key=lambda item: int(item["EVT_ID"])):
        event = migrate_event(row)
        if event["evt_id"] in present:
            continue
        target.append(event)
        present.add(event["evt_id"])

    return target
